// scanAuthorTags scans rows into AuthorTag entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanAuthorTags(rows database.Rows, columns []string) ([]*AuthorTag, error) {
	var result []*AuthorTag
	for rows.Next() {
		a := &AuthorTag{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "author_id":
				targets[idx] = &a.AuthorID
			case "tag_id":
				targets[idx] = &a.TagID
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan author_tag: %w", err)
		}

		result = append(result, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate author_tag rows: %w", err)
	}
	return result, nil
}

